CREATE PROCEDURE "informix".sp_catalogotipoadminpmgobierno(pUsuario CHAR(8), pIdFuncion CHAR(10), pCodigo CHAR(3), pTipoOrden SMALLINT)
		RETURNING CHAR(5) AS codret,
				CHAR(3) AS codigo,
				CHAR(20) AS descripcion;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cCodigo CHAR(3);
	DEFINE cDescripcion CHAR(20);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET cCodigo = '';
	LET cDescripcion = '';

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cCodigo, cDescripcion;
		END EXCEPTION;

		-- SET DEBUG FILE TO '/tmp/mfinis/sp_catalogotipoadminpmgobierno.out';
		-- TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pTipoOrden IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cCodigo, cDescripcion;
		END IF;

		IF pTipoOrden NOT IN (1, 2) THEN
			LET cCodRet = '00044';
			RETURN cCodRet, cCodigo, cDescripcion;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cCodigo, cDescripcion;
		END IF;

		FOREACH EXECUTE PROCEDURE bdinteg:"informix".sp_tipo_admin_pm_gobierno(cEmpresa, pCodigo, pTipoOrden)
			INTO cCodRetSp, cEmpresa, cCodigo, cDescripcion

			LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP sp_tipo_admin_pm_gobierno';
			ELIF iCodRetSp = 3 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cCodigo, cDescripcion;
			END IF;

			RETURN cCodRet, UPPER(cCodigo), UPPER(cDescripcion) WITH RESUME;

		END FOREACH;

	END;

END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 26/05/2014',
