			LET cCodRet = '00003';
			RETURN cCodRet, iNumRegistros;
		ELIF cCodRetSp::INTEGER = 3 THEN 
			LET cCodRet = '00017';
			RETURN cCodRet, iNumRegistros;
		END IF;

		IF NVL(iNumRegistros,0) = 0 THEN
			LET cCodRet = '00017';
		END IF;

		RETURN cCodRet, iNumRegistros;

	END;	
